import "server-only";

import { DomainError } from "@/server/errors";

/**
 * Poster storage keys are generated by the server and are never derived from a
 * browser filename. Keeping the format in one module lets every adapter apply
 * the same path-traversal and type restrictions.
 */
const POSTER_KEY_PATTERN =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}\.(jpg|png|webp)$/i;

export function isPosterStorageKey(value: string): boolean {
  return POSTER_KEY_PATTERN.test(value);
}

export function posterStorageError(): DomainError {
  return new DomainError(
    "STORAGE_ERROR",
    "The poster file could not be processed. Please try again.",
    500,
  );
}
